def choose_move(observation):
    sx, sy = observation.get("self_position", [0, 0])
    ox, oy = observation.get("opponent_position", [0, 0])
    env = observation.get("environment_name", "resource_collection")
    resources = observation.get("resources") or []
    unclaimed = observation.get("unclaimed_cells") or []
    opponent_territory = observation.get("opponent_territory") or []
    grid_width = observation.get("grid_width", 1)
    grid_height = observation.get("grid_height", 1)
    role = observation.get("self_role", "pursuer")

    def move_towards(target_x, target_y):
        dx = 0 if target_x == sx else (1 if target_x > sx else -1)
        dy = 0 if target_y == sy else (1 if target_y > sy else -1)
        return dx, dy

    if env == "pursuit_evasion":
        if role == "pursuer":
            dx, dy = move_towards(ox, oy)
            return [dx, dy]
        corners = [
            [0, 0],
            [0, grid_height - 1],
            [grid_width - 1, 0],
            [grid_width - 1, grid_height - 1],
        ]
        target = min(corners, key=lambda item: abs(item[0] - ox) + abs(item[1] - oy))
        return list(move_towards(target[0], target[1]))
    if env == "territory_control":
        targets = unclaimed or opponent_territory or []
        if not targets:
            return [0, 0]
        best = min(targets, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
        return list(move_towards(best[0], best[1]))
    if resources:
        best = min(resources, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
        return list(move_towards(best[0], best[1]))
    return [0, 0]

